/**
 * 888 2FA - Brand Assets & Icons
 * Automatically generated high-resolution brand assets for PWA and Open Graph
 * Minimalist Cyber Orange (#F95700) with Pure White Typography (888 / 2FA)
 */

export const BRAND_SVG =
	'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512">\n  <rect x="16" y="16" width="480" height="480" rx="112" fill="#F95700" />\n  <g fill="#FFFFFF" text-anchor="middle" font-family="system-ui, -apple-system, BlinkMacSystemFont, \'SF Pro Display\', Inter, sans-serif">\n    <text x="256" y="238" font-size="148" font-weight="900" letter-spacing="4">888</text>\n    <text x="256" y="372" font-size="124" font-weight="900" letter-spacing="6">2FA</text>\n  </g>\n</svg>';

export const FAVICON_32_PNG =
	'';

export const FAVICON_16_PNG =
	'';

export const APPLE_TOUCH_ICON_PNG =
	'';

export const ICON_192_PNG =
	'';

export const ICON_512_PNG =
	'';

export const OG_IMAGE_JPEG =
	'';

function base64ToUint8Array(base64) {
	const binary = atob(base64);
	const len = binary.length;
	const bytes = new Uint8Array(len);
	for (let i = 0; i < len; i++) {
		bytes[i] = binary.charCodeAt(i);
	}
	return bytes;
}

export function createBrandAssetResponse(assetType) {
	switch (assetType) {
		case 'svg':
			return new Response(BRAND_SVG, {
				status: 200,
				headers: {
					'Content-Type': 'image/svg+xml; charset=utf-8',
					'Cache-Control': 'public, max-age=604800, immutable',
					'Access-Control-Allow-Origin': '*',
				},
			});

		case 'favicon-32':
			return new Response(base64ToUint8Array(FAVICON_32_PNG), {
				status: 200,
				headers: {
					'Content-Type': 'image/png',
					'Cache-Control': 'public, max-age=604800, immutable',
					'Access-Control-Allow-Origin': '*',
				},
			});

		case 'favicon-16':
			return new Response(base64ToUint8Array(FAVICON_16_PNG), {
				status: 200,
				headers: {
					'Content-Type': 'image/png',
					'Cache-Control': 'public, max-age=604800, immutable',
					'Access-Control-Allow-Origin': '*',
				},
			});

		case 'favicon-ico':
			return new Response(base64ToUint8Array(FAVICON_32_PNG), {
				status: 200,
				headers: {
					'Content-Type': 'image/x-icon',
					'Cache-Control': 'public, max-age=604800, immutable',
					'Access-Control-Allow-Origin': '*',
				},
			});

		case 'apple-touch-icon':
			return new Response(base64ToUint8Array(APPLE_TOUCH_ICON_PNG), {
				status: 200,
				headers: {
					'Content-Type': 'image/png',
					'Cache-Control': 'public, max-age=604800, immutable',
					'Access-Control-Allow-Origin': '*',
				},
			});

		case 'icon-192':
			return new Response(base64ToUint8Array(ICON_192_PNG), {
				status: 200,
				headers: {
					'Content-Type': 'image/png',
					'Cache-Control': 'public, max-age=604800, immutable',
					'Access-Control-Allow-Origin': '*',
				},
			});

		case 'icon-512':
			return new Response(base64ToUint8Array(ICON_512_PNG), {
				status: 200,
				headers: {
					'Content-Type': 'image/png',
					'Cache-Control': 'public, max-age=604800, immutable',
					'Access-Control-Allow-Origin': '*',
				},
			});

		case 'og-image':
			return new Response(base64ToUint8Array(OG_IMAGE_JPEG), {
				status: 200,
				headers: {
					'Content-Type': 'image/jpeg',
					'Cache-Control': 'public, max-age=604800, immutable',
					'Access-Control-Allow-Origin': '*',
				},
			});

		default:
			return new Response('Asset Not Found', { status: 404 });
	}
}
